describe('Stale Record Conflict Error Handling', () => {
  const apiUrl = 'http://localhost:3000/api';
  const recordId = '12345';
  let initialEtag = '"1-abc123"';
  let updatedEtag = '"2-def456"';

  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.intercept('GET', `${apiUrl}/records/${recordId}`, {
      statusCode: 200,
      body: {
        id: recordId,
        name: 'Test Record',
        value: 'Initial Value'
      },
      headers: {
        'ETag': initialEtag
      }
    }).as('getRecord');

    cy.intercept('PUT', `${apiUrl}/records/${recordId}`, (req) => {
      if (req.headers['if-match'] !== updatedEtag) {
        req.reply({
          statusCode: 409,
          body: {
            error: 'Conflict',
            message: 'The record has been modified by another user. Please refresh and try again.'
          }
        });
      } else {
        req.reply({
          statusCode: 200,
          body: {
            id: recordId,
            name: 'Test Record',
            value: 'Updated Value'
          }
        });
      }
    }).as('updateRecord');
  });

  it('should display conflict error message when saving a stale record', () => {
    cy.get('[data-testid="record-form"]').should('exist');
    cy.get('[data-testid="record-input"]').clear().type('Updated Value');
    cy.get('[data-testid="save-button"]').click();

    cy.wait('@updateRecord');
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'The record has been modified by another user');
    cy.get('[data-testid="error-message"]')
      .should('have.class', 'error-alert');
  });

  it('should successfully save record when ETag matches current version', () => {
    cy.get('[data-testid="record-form"]').should('exist');
    cy.get('[data-testid="record-input"]').clear().type('Updated Value');

    cy.intercept('PUT', `${apiUrl}/records/${recordId}`, (req) => {
      req.headers['if-match'] = updatedEtag;
      req.reply({
        statusCode: 200,
        body: {
          id: recordId,
          name: 'Test Record',
          value: 'Updated Value'
        }
      });
    }).as('updateRecordSuccess');

    cy.get('[data-testid="save-button"]').click();
    cy.wait('@updateRecordSuccess');

    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'Record saved successfully');
    cy.get('[data-testid="error-message"]').should('not.exist');
  });

  it('should handle multiple consecutive save attempts with stale data', () => {
    cy.get('[data-testid="record-input"]').clear().type('First Update');
    cy.get('[data-testid="save-button"]').click();
    cy.wait('@updateRecord');

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Conflict');

    cy.get('[data-testid="record-input"]').clear().type('Second Update');
    cy.get('[data-testid="save-button"]').click();
    cy.wait('@updateRecord');

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'The record has been modified by another user');
  });
});
